import math
from functools import reduce

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a*b) // gcd(a, b)

def calculate_x_k(k, n):
    """Calculates x_k = lcm(k, k+1, ..., k+n-1)"""
    if n <= 0:
        return 1 # Or handle as error, though n is positive integer
    numbers = range(k, k + n)
    if not numbers:
        return 1

    def range_lcm(a, b):
        return lcm(a, b)

    return reduce(range_lcm, numbers)

results = {}
N_MAX = 5
K_MAX = 30
Ns_to_test = [3, 4, 5]

print("Starting computational check for n=3, 4, 5 up to k=29.")

for n in Ns_to_test:
    results[n] = []
    print(f"\n--- Testing n = {n} ---")

    # We check k from 1 up to K_MAX - 1 = 29
    for k in range(1, K_MAX):
        x_k = calculate_x_k(k, n)
        x_k_plus_1 = calculate_x_k(k + 1, n)

        comparison = "Increasing" if x_k_plus_1 > x_k else "Non-increasing"

        # Store detailed results for review, but only print key findings
        results[n].append({
            'k': k,
            'x_k': x_k,
            'x_k_plus_1': x_k_plus_1,
            'comparison': comparison
        })

        # Print status update for debugging/tracking
        if k < 10 or k % 5 == 0 or k == K_MAX - 1:
            print(f"k={k}: x_k={x_k} ({len(str(x_k))}-digits) -> x_{k+1}={x_k_plus_1} ({len(str(x_k_plus_1))}-digits). Status: {comparison}")

# Summarize findings
summary = {}
for n in Ns_to_test:
    failures = [r['k'] for r in results[n] if r['comparison'] == "Non-increasing"]

    # Check if there are any failures at all
    if not failures:
        summary[n] = "All k checked (1 to 29) showed x_{k+1} > x_k."
    else:
        # Check if the failures are isolated or if they continue to occur
        # For simplicity, we report if any failure occurred in the range.
        summary[n] = f"Failures found at k = {failures[:5]}... (Total {len(failures)} failures found up to k=29)."

print("\n===== SUMMARY =====")
for n, s in summary.items():
    print(f"n={n}: {s}")
